WITH unpacked AS (SELECT id, plan, currency, tier_prices, discounts, AGGREGATE(tier_prices, CAST(0 AS DOUBLE), (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price, SLICE(tier_limits, 1, 2) AS first_two_limits FROM price_tiers) SELECT *, SUM(avg_tier_price) OVER (PARTITION BY plan, currency ORDER BY avg_tier_price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_avg_tier_price, NTILE(3) OVER (PARTITION BY currency ORDER BY avg_tier_price DESC, id) AS avg_tier_price_bucket FROM unpacked WHERE avg_tier_price < 25
